$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$route = Decode ""

$financePath = Join-Path $root "app\api\provider\finance\route.ts"
$auditPath = Join-Path $root "app\api\provider\finance-audit\route.ts"
$paymentsPage = Join-Path $root "app\provider\payments\page.tsx"

foreach ($path in @($financePath, $auditPath, $paymentsPage)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.04 : fichier requis introuvable : $path"
    }
}

$audit = [System.IO.File]::ReadAllText($auditPath)

if (-not $audit.Contains("KLYX_GROUP_FINANCE_AUDIT_API_13_03")) {
    throw "13.04 : KLYX 13.03 introuvable."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $financePath -Destination ($financePath + ".bak-13-04-" + $timestamp) -Force

[System.IO.File]::WriteAllText($financePath, $route, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.04 APPLIQUE"
Write-Host "======================================"
Write-Host "PaymentIntent = 1 evenement : OUI"
Write-Host "Refund = 1 evenement : OUI"
Write-Host "Booking group = 1 scope : OUI"
Write-Host "Comptages ledger bruts : AUDITABLES"
Write-Host "Montants modifies : NON"
Write-Host "Stripe modifie : NON"
Write-Host "======================================"
